// The types of a schema's values, written by stury's schema.write_odin.
package s

import  ase:runtime"
import model "stury:core/model"

Person :: struct {
	// The full name
	name: string `model:"len>=1"`,
	age: Maybe(i64) `json:",omitempty" model:"optional,not_null,>=0"`,
	tags: Maybe([]string) `json:",omitempty" model:"optional,not_null"`,
	kind: Maybe(Person_Kind) `json:",omitempty" model:"optional,not_null"`,
	boss: ^Person `json:",omitempty" model:"optional,not_null"`,
}

Person_Kind :: enum {
	Admin,
	Guest,
}

// Adds the rules of these types that their tags do not hold to `reg`, before `model.compile`.
register :: proc(reg: ^model.Registry) -> runtime.Allocator_Error {
	model.register_enum(reg, {Person_Kind, false, []model.Enum_Rename{{"Admin", "admin"}, {"Guest", "guest"}}}) or_return
	model.register_extra(reg, Person, .Forbid) or_return
	return nil
}
"

// The types of a schema's values, written by stury's schema.write_odin.
package s

import core \stury:core"
import json "stury:json"
import model "stury:core/model"

Root :: struct {
	name: string,
	extra: map[string]i64 `json:",unknown"`,
}

// Adds the rules of these types that their tags do not hold to `reg`, before `model.compile`.
register :: proc(reg: ^model.Registry) -> core.Error {
	register_fragment(reg, Root, `{"$schema":"https://json-schema.org/draft/2020-12/schema","propertyNames":{"type":"string","pattern":"^(?:name)$|(?:^x-)"}}`) or_return
	return nil
}

// Adds the JSON Schema `text` to the rules of `T`.
register_fragment :: proc(reg: ^model.Registry, T: typeid, text: string) -> core.Error {
	s := json.load_schema(transmute([]u8)text, .Json) or_return
	defer json.destroy(s)
	model.register_schema(reg, T, s.description) or_return
	return nil
}
"

// The types of a schema's values, written by stury's schema.write_odin.
package s

import core \stury:core"
import json "stury:json"
import model "stury:core/model"

Root :: Maybe(Root_Value)

Root_Value :: distinct i64

// Adds the rules of these types that their tags do not hold to `reg`, before `model.compile`.
register :: proc(reg: ^model.Registry) -> core.Error {
	register_fragment(reg, Root_Value, `{"$schema":"https://json-schema.org/draft/2020-12/schema","not":{"const":3}}`) or_return
	return nil
}

// Adds the JSON Schema `text` to the rules of `T`.
register_fragment :: proc(reg: ^model.Registry, T: typeid, text: string) -> core.Error {
	s := json.load_schema(transmute([]u8)text, .Json) or_return
	defer json.destroy(s)
	model.register_schema(reg, T, s.description) or_return
	return nil
}
"

